// Deno Edge Function — server SDP for Poppins WebRTC duplex (POST /v1/realtime/calls).
// Never returns OPENAI_API_KEY. Client sends JSON { sdp, session fields }; response is text/plain SDP
// (not application/sdp — iOS 27 RCTBlobManager/UTType aborts on that MIME).

import {
  corsHeaders,
  jsonResponse,
  requireActiveMember,
  aiConsentRequired,
} from '../_shared/poppins-auth.ts';
import {
  buildPoppinsRealtimeSessionConfig,
  voiceAccessAllowed,
} from '../_shared/poppins-realtime-session-config.ts';
import { recordAiUsageEvent } from '../_shared/ai-usage.ts';

async function sha256Hex(input: string): Promise<string> {
  const data = new TextEncoder().encode(input);
  const digest = await crypto.subtle.digest('SHA-256', data);
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const authHeader = req.headers.get('Authorization');
    const contentType = req.headers.get('Content-Type') ?? '';

    let householdId: string | undefined;
    let majordomoProfileId: string | undefined;
    let voiceId: string | undefined;
    let householdContext: Record<string, unknown> | undefined;
    let pageContext: string | undefined;
    let capabilityProfile: string | undefined;
    let isPremium: boolean | undefined;
    let trialActive: boolean | undefined;
    let billingPending: boolean | undefined;
    let sdpOffer = '';

    if (contentType.includes('multipart/form-data')) {
      const form = await req.formData();
      const sdpPart = form.get('sdp');
      sdpOffer = typeof sdpPart === 'string' ? sdpPart : sdpPart ? await (sdpPart as Blob).text() : '';
      const ctxRaw = form.get('session');
      if (typeof ctxRaw === 'string') {
        try {
          const parsed = JSON.parse(ctxRaw) as Record<string, unknown>;
          householdId = parsed.householdId as string | undefined;
          majordomoProfileId = parsed.majordomoProfileId as string | undefined;
          voiceId = parsed.voiceId as string | undefined;
          householdContext = parsed.householdContext as Record<string, unknown> | undefined;
          pageContext = parsed.pageContext as string | undefined;
          capabilityProfile = parsed.capabilityProfile as string | undefined;
          isPremium = parsed.isPremium as boolean | undefined;
          trialActive = parsed.trialActive as boolean | undefined;
          billingPending = parsed.billingPending as boolean | undefined;
        } catch {
          /* ignore */
        }
      }
      householdId = householdId ?? (form.get('householdId') as string | undefined);
    } else {
      const body = await req.json().catch(() => ({}));
      sdpOffer = String(body.sdp ?? '');
      householdId = body.householdId as string | undefined;
      majordomoProfileId =
        (body.majordomoProfileId as string | undefined) ??
        (body.householdContext?.majordomoProfileId as string | undefined);
      voiceId = body.voiceId as string | undefined;
      householdContext = body.householdContext as Record<string, unknown> | undefined;
      pageContext = body.pageContext as string | undefined;
      capabilityProfile = body.capabilityProfile as string | undefined;
      isPremium = body.isPremium as boolean | undefined;
      trialActive = body.trialActive as boolean | undefined;
      billingPending = body.billingPending as boolean | undefined;
    }

    if (!sdpOffer.trim()) {
      return jsonResponse({ error: 'sdp offer required' }, 400);
    }

    const auth = await requireActiveMember(authHeader, householdId);
    if (auth.error) {
      return auth.error;
    }
    // App Review 5.1.2(i): never send this person's words to OpenAI without their permission.
    if (!auth.aiConsent) return aiConsentRequired();

    const access = voiceAccessAllowed({ isPremium, trialActive, billingPending });
    if (!access.ok) {
      return jsonResponse({ error: access.reason ?? 'voice_not_allowed', fallback: 'text' }, 402);
    }

    const openaiKey = Deno.env.get('OPENAI_API_KEY');
    if (!openaiKey) {
      return jsonResponse({ error: 'OPENAI_API_KEY not configured', fallback: 'whisper' }, 503);
    }

    const profileId =
      majordomoProfileId ??
      (householdContext?.majordomoProfileId as string | undefined) ??
      'poppins';
    const deskHint = householdContext?.desk
      ? ` Desk brief: ${JSON.stringify(householdContext.desk).slice(0, 2000)}.`
      : '';
    const householdHint = householdContext
      ? ` Household context: ${JSON.stringify(householdContext).slice(0, 5000)}`
      : '';

    const { session, profile, model, voice } = buildPoppinsRealtimeSessionConfig({
      profileId,
      voiceId,
      memberRole: auth.membership?.role ?? 'adult',
      deskHint,
      householdHint,
      pageContext,
      capabilityProfile,
    });

    const safetyId = await sha256Hex(auth.user.id);
    const form = new FormData();
    form.set('sdp', sdpOffer);
    form.set('session', JSON.stringify(session));

    const openaiRes = await fetch('https://api.openai.com/v1/realtime/calls', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${openaiKey}`,
        'OpenAI-Safety-Identifier': safetyId,
      },
      body: form,
    });

    const answerSdp = await openaiRes.text();
    if (!openaiRes.ok) {
      let details: unknown = answerSdp;
      try {
        details = JSON.parse(answerSdp);
      } catch {
        /* keep text */
      }
      return jsonResponse(
        {
          error: 'Failed to create Realtime WebRTC call',
          fallback: 'whisper',
          details,
          model,
        },
        openaiRes.status >= 400 ? openaiRes.status : 502
      );
    }

    const sessionId = householdId ? `realtime-sdp-${householdId}-${Date.now()}` : null;
    if (householdId && sessionId) {
      await recordAiUsageEvent({
        householdId: String(householdId),
        clientKey: `${sessionId}-${Math.random().toString(36).slice(2, 8)}`,
        memberId: auth.user?.id,
        kind: 'realtime',
        model: String(model),
        inputTokens: 0,
        outputTokens: 0,
        surface: 'poppins-realtime-sdp',
        mode: 'sdp',
        sessionId,
        turnIndex: null,
      });
    }

    return new Response(answerSdp, {
      status: 200,
      headers: {
        ...corsHeaders,
        'Content-Type': 'text/plain; charset=utf-8',
        'Cache-Control': 'no-store',
        'X-Poppins-Realtime-Model': model,
        'X-Poppins-Voice': voice,
        'X-Poppins-Majordomo': profile.id,
        ...(sessionId ? { 'X-Poppins-Session-Id': sessionId } : {}),
      },
    });
  } catch (error) {
    return jsonResponse({ error: String(error), fallback: 'whisper' }, 500);
  }
});

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.49.1';

export const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

export function jsonResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

function isSidekickRole(role: string | null | undefined) {
  return role === 'child' || role === 'sidekick';
}

/** Poppins is always 403 for Sidekicks — there is no household switch for it. */
export function requireNonSidekick(
  role: string | null | undefined,
  options?: { allowed?: boolean }
) {
  if (isSidekickRole(role) && !options?.allowed) {
    return jsonResponse({ error: 'Poppins is not available on this profile.' }, 403);
  }
  return null;
}

export async function requireActiveMember(
  authHeader: string | null,
  householdId: string | null | undefined
) {
  if (!authHeader) {
    return { error: jsonResponse({ error: 'Unauthorized' }, 401) };
  }

  const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
  const anonKey = Deno.env.get('SUPABASE_ANON_KEY')!;
  const userClient = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: authHeader } },
  });

  const {
    data: { user },
    error: userError,
  } = await userClient.auth.getUser();

  if (userError || !user) {
    return { error: jsonResponse({ error: 'Unauthorized' }, 401) };
  }

  if (!householdId) {
    return { error: jsonResponse({ error: 'householdId required' }, 400) };
  }

  const { data: membership, error: memberError } = await userClient
    .from('household_members')
    .select('id, role, status, display_name')
    .eq('household_id', householdId)
    .eq('user_id', user.id)
    .maybeSingle();

  if (memberError || !membership || membership.status !== 'active') {
    return { error: jsonResponse({ error: 'Active household membership required' }, 403) };
  }

  // Sidekicks never get Poppins, whatever the household row says.
  const sidekickBlock = requireNonSidekick(membership.role, { allowed: false });
  if (sidekickBlock) {
    return { error: sidekickBlock };
  }

  // App Review 5.1.2(i): nothing goes to OpenAI for a person who has not allowed it.
  const { data: profile } = await userClient
    .from('profiles')
    .select('ai_consent_at')
    .eq('id', user.id)
    .maybeSingle();
  const aiConsent = Boolean((profile as { ai_consent_at?: string | null } | null)?.ai_consent_at);

  return { user, membership, userClient, aiConsent };
}

/** The reply when a person has not allowed Poppins to use OpenAI. The app shows its consent sheet. */
export function aiConsentRequired() {
  return jsonResponse(
    { error: 'ai_consent_required', message: 'Allow Poppins to use OpenAI in the app first.' },
    403
  );
}

export function buildCompactHouseholdContext(household: Record<string, unknown> | null | undefined) {
  if (!household || typeof household !== 'object') {
    return {};
  }

  const tasks = Array.isArray(household.tasks) ? household.tasks : [];
  const groceries = Array.isArray(household.groceries) ? household.groceries : [];
  const events = Array.isArray(household.events) ? household.events : [];
  const members = Array.isArray(household.members) ? household.members : [];

  return {
    householdName: household.householdName ?? household.household_name,
    greetingName: household.greetingName ?? household.greeting_name,
    openTasks: tasks
      .filter((t: { status?: string }) => t.status !== 'Completed' && t.status !== 'completed')
      .slice(0, 8)
      .map((t: { title?: string; assignee?: string; due?: string; status?: string }) => ({
        title: t.title,
        assignee: t.assignee,
        due: t.due,
        status: t.status,
      })),
    missingGroceries: groceries
      .filter((g: { status?: string }) => g.status === 'Missing' || g.status === 'missing')
      .slice(0, 6)
      .map((g: { name?: string; category?: string }) => ({ name: g.name, category: g.category })),
    upcomingEvents: events.slice(0, 5).map((e: { title?: string; date?: string; time?: string }) => ({
      title: e.title,
      date: e.date,
      time: e.time,
    })),
    members: members
      .filter((m: { status?: string }) => m.status === 'active')
      .map((m: { name?: string; role?: string; weekXp?: number; xp?: number; streak?: number }) => ({
        name: m.name,
        role: m.role,
        weekXp: m.weekXp ?? m.week_xp,
        xp: m.xp,
        streak: m.streak,
      })),
  };
}

/**
 * Shared Realtime session config for poppins-realtime-sdp (WebRTC) and ephemeral mint.
 */

import {
  getOpenAIInputTranscribeModel,
  getOpenAIRealtimeModel,
  resolveRealtimeReasoningEffort,
} from './openai-models.ts';
import { REALTIME_POST_INSTRUCTIONS_TOKEN_LIMIT } from './openai-rates.ts';
import {
  buildMajordomoSystemPrompt,
  getMajordomoProfile,
  poppinsToolsAsRealtimeTools,
  resolveRequestedVoice,
} from './poppins-tools.ts';

const IDLE_RAILS = `
Voice cost rails (smart idle hangup — not a farewell ritual):
- Prefer ending via end_session when the request is clearly done and the user said thanks/bye or there is no follow-up.
- Soft idle is client-enforced (~15s silence); do not invent a spoken “still there?” check-in.
- Never invent a long “anything else?” ceremony. Keep answers short while tools run.
- After tools, always continue speaking a short spoken summary — never stay silent in Thinking.
- Consequential / risky actions must stage confirmation; never silently delete, approve money/rewards, remove members, or wipe lists.
- Never expose deleteAccount, signOut, or auth routes.
`;

export type BuildRealtimeSessionInput = {
  profileId?: string | null;
  memberRole?: string | null;
  deskHint?: string;
  householdHint?: string;
  pageContext?: string;
  capabilityProfile?: string;
  softPromptMs?: number;
  idleHangupMs?: number;
  /** Voice colour chosen on the wheel. Wins over the profile's own voice. */
  voiceId?: string | null;
};

export function buildPoppinsRealtimeInstructions(input: BuildRealtimeSessionInput): string {
  const profileId = input.profileId ?? 'poppins';
  const memberRole = input.memberRole ?? 'adult';
  const soft = input.softPromptMs ?? Number(Deno.env.get('POPPINS_VOICE_SOFT_PROMPT_MS') ?? 15000);
  const idle = input.idleHangupMs ?? Number(Deno.env.get('POPPINS_VOICE_IDLE_MS') ?? 30000);

  return (
    `${buildMajordomoSystemPrompt(profileId, memberRole)}\n` +
    'Speak calmly and briefly (one short sentence per beat). Wait for a tap or HOLD before adding another idea.\n' +
    `Idle timing hints: soft idle ~${soft}ms, hangup ~${idle}ms of silence (client-enforced; no spoken check-in).\n` +
    IDLE_RAILS +
    (input.capabilityProfile ? `\nCapability focus: ${input.capabilityProfile}.` : '') +
    (input.pageContext ? `\nPage context: ${input.pageContext}` : '') +
    (input.deskHint ?? '') +
    (input.householdHint ?? '')
  );
}

export function buildPoppinsRealtimeSessionConfig(input: BuildRealtimeSessionInput) {
  const profile = getMajordomoProfile(input.profileId ?? 'poppins');
  const voice = resolveRequestedVoice(input.voiceId) ?? profile.voice;
  const model = getOpenAIRealtimeModel();
  const instructions = buildPoppinsRealtimeInstructions(input);
  // Patient profiles: slightly less eager VAD / interrupt.
  const patient = profile.id === 'companion' || profile.id === 'advisor';
  const reasoningEffort = resolveRealtimeReasoningEffort('low');

  const session: Record<string, unknown> = {
    type: 'realtime',
    model,
    instructions,
    tools: poppinsToolsAsRealtimeTools(),
    tool_choice: 'auto',
    // ESTIMATED ~2 audio turns — OpenAI has no turn-count truncation; see REALTIME_POST_INSTRUCTIONS_TOKEN_LIMIT.
    truncation: {
      type: 'retention_ratio',
      retention_ratio: 0.8,
      token_limits: {
        post_instructions: REALTIME_POST_INSTRUCTIONS_TOKEN_LIMIT,
      },
    },
    audio: {
      input: {
        noise_reduction: { type: 'near_field' },
        transcription: {
          model: getOpenAIInputTranscribeModel(),
          // English only. Left to guess, it heard accented English as French and the model
          // answered in French.
          language: 'en',
        },
        turn_detection: {
          type: 'semantic_vad',
          eagerness: patient ? 'low' : 'medium',
          create_response: true,
          interrupt_response: !patient,
        },
      },
      output: {
        voice,
      },
    },
  };

  if (reasoningEffort) {
    session.reasoning = { effort: reasoningEffort };
  }

  return { session, profile, model, instructions, voice };
}

/** Soft premium / trial gate for live duplex voice. */
export function voiceAccessAllowed(flags?: {
  isPremium?: boolean;
  trialActive?: boolean;
  billingPending?: boolean;
}): { ok: boolean; reason?: string } {
  if (Deno.env.get('POPPINS_VOICE_GRANT_ALL') === '1') {
    return { ok: true };
  }
  if (flags?.billingPending) {
    // Soft-gate: allow during TestFlight billing pending.
    return { ok: true };
  }
  if (flags?.isPremium || flags?.trialActive) {
    return { ok: true };
  }
  // Default allow for staging TestFlight when flags omitted; client still needs auth membership.
  if (flags == null || (flags.isPremium == null && flags.trialActive == null)) {
    return { ok: true };
  }
  return { ok: false, reason: 'premium_or_trial_required' };
}

// Deno — Poppins model IDs (mirrors lib/ai/openai-models.ts)

export const DEFAULT_OPENAI_REALTIME_MODEL = 'gpt-realtime-2.1';
export const DEFAULT_OPENAI_POPPINS_CHAT_MODEL = 'gpt-5.6-luna';
export const DEFAULT_OPENAI_INPUT_TRANSCRIBE_MODEL = 'gpt-4o-mini-transcribe';

export function getOpenAIRealtimeModel(): string {
  return Deno.env.get('OPENAI_REALTIME_MODEL')?.trim() || DEFAULT_OPENAI_REALTIME_MODEL;
}

export function getOpenAIPoppinsChatModel(): string {
  return Deno.env.get('OPENAI_POPPINS_CHAT_MODEL')?.trim() || DEFAULT_OPENAI_POPPINS_CHAT_MODEL;
}

export function getOpenAIInputTranscribeModel(): string {
  return (
    Deno.env.get('OPENAI_INPUT_TRANSCRIBE_MODEL')?.trim() || DEFAULT_OPENAI_INPUT_TRANSCRIBE_MODEL
  );
}

export function getOpenAIRealtimeReasoningMode(): 'auto' | 'on' | 'off' {
  const raw = (Deno.env.get('OPENAI_REALTIME_REASONING') ?? 'auto').trim().toLowerCase();
  if (raw === 'off' || raw === 'on') return raw;
  return 'auto';
}

export function realtimeModelSupportsReasoning(model: string): boolean {
  return /gpt-realtime-2(\.|$)/i.test(model);
}

export function resolveRealtimeReasoningEffort(
  personalityEffort?: 'off' | 'minimal' | 'low' | 'medium' | 'high' | 'xhigh'
): 'minimal' | 'low' | 'medium' | 'high' | 'xhigh' | null {
  const mode = getOpenAIRealtimeReasoningMode();
  const model = getOpenAIRealtimeModel();
  if (!realtimeModelSupportsReasoning(model) || mode === 'off') return null;
  if (personalityEffort === 'off') return null;
  if (mode === 'on') {
    return personalityEffort && personalityEffort !== 'off' ? personalityEffort : 'low';
  }
  return personalityEffort && personalityEffort !== 'off' ? personalityEffort : 'low';
}

/**
 * Edge copy of constants/poppins-ai-rates.ts — keep in sync.
 * MEASURED = OpenAI public pricing Sep 2026. ESTIMATED = fallback.
 */

export type ModelTokenRate = {
  input: number;
  output: number;
  source: 'MEASURED' | 'ESTIMATED';
};

export const MODEL_RATES_USD_PER_MILLION: Record<string, ModelTokenRate> = {
  'gpt-5.6-luna': { input: 0.2, output: 1.2, source: 'MEASURED' },
  'gpt-5.6-terra': { input: 2, output: 12, source: 'MEASURED' },
  'gpt-4o': { input: 2.5, output: 10, source: 'MEASURED' },
  'gpt-4o-mini': { input: 0.15, output: 0.6, source: 'MEASURED' },
  'gpt-4o-mini-transcribe': { input: 1.25, output: 0, source: 'MEASURED' },
  'gpt-realtime-2.1': { input: 32, output: 64, source: 'MEASURED' },
  default: { input: 0.2, output: 1.2, source: 'MEASURED' },
};

export const POPPINS_MONITOR_MODEL_CALLS_PER_DAY = 3;
export const POPPINS_MONITOR_MAX_ROUNDS = 2;
export const POPPINS_MONITOR_MODEL_DEFAULT = 'off';
export const POPPINS_ACTS_PER_DAY_DEFAULT = 300;
/** Local hours (household TZ) when monitor may call the model. */
export const POPPINS_MONITOR_ACTIVE_HOURS = [8, 15, 18, 20] as const;

/**
 * Realtime truncation post_instructions ceiling (ESTIMATED ~2 audio turns).
 * Keep in sync with constants/poppins-ai-rates.ts.
 */
export const REALTIME_POST_INSTRUCTIONS_TOKEN_LIMIT = 4000;

export function ratesForModel(model: string): { input: number; output: number } {
  const key = model.trim() || 'default';
  const row = MODEL_RATES_USD_PER_MILLION[key] ?? MODEL_RATES_USD_PER_MILLION.default;
  return { input: row.input, output: row.output };
}

export function usdForTokens(inputTokens: number, outputTokens: number, model: string): number {
  const rates = ratesForModel(model);
  const usd =
    (Math.max(0, inputTokens) / 1_000_000) * rates.input +
    (Math.max(0, outputTokens) / 1_000_000) * rates.output;
  return Math.round(Math.max(0, usd) * 10_000) / 10_000;
}

/** POPPINS_MONITOR_MODEL secret: on | 1 | true enables model loop. Default off. */
export function isMonitorModelEnabled(): boolean {
  const raw = (Deno.env.get('POPPINS_MONITOR_MODEL') ?? POPPINS_MONITOR_MODEL_DEFAULT).trim().toLowerCase();
  return raw === 'on' || raw === '1' || raw === 'true';
}

export function getActsPerDayCap(): number {
  const raw = Deno.env.get('POPPINS_ACTS_PER_DAY');
  const n = raw ? Number(raw) : POPPINS_ACTS_PER_DAY_DEFAULT;
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : POPPINS_ACTS_PER_DAY_DEFAULT;
}

/** Shared Poppins tool registry (mirrors lib/ai/poppins-tools.ts). Prompt → majordomo-profiles. */

export {
  POPPINS_MAJORDOMO_SYSTEM,
  buildMajordomoSystemPrompt,
  getMajordomoProfile,
  resolveMajordomoProfileId,
  DEFAULT_MAJORDOMO_PROFILE_ID,
  MAJORDOMO_PROFILES,
  MAJORDOMO_VOICE_IDS,
  resolveRequestedVoice,
} from './majordomo-profiles.ts';

