  | 'search_house_rules'
  | 'get_pending_approvals'
  | 'get_briefing_snapshot'
  | 'get_unread_notifications'
  | 'list_itineraries'
  | 'get_smart_home_state'
  | 'create_task_draft'
  | 'assign_task'
  | 'update_task'
  | 'complete_task'
  | 'create_calendar_event'
  | 'create_itinerary'
  | 'resolve_place'
  | 'list_saved_places'
