export type PoppinsToolRisk = 'safe_parallel' | 'safe_serial' | 'risky' | 'session';

export type PoppinsToolDefinition = {
  name: PoppinsToolName;
  description: string;
  parameters: Record<string, unknown>;
  risk: PoppinsToolRisk;
};

/** Allowlisted in-app routes for navigate_to. */
export const POPPINS_NAV_ROUTES = [
  '/(tabs)',
  '/(tabs)/tasks',
  '/(tabs)/calendar',
  '/(tabs)/rewards',
  '/(tabs)/poppins',
  '/(tabs)/groceries',
  '/shopping-mode',
  '/create-task',
  '/assign-task',
  '/create-event',
  '/create-itinerary',
  '/create-reward',
  '/create-allowance',
  '/grant-allowance',
  '/house-rules',
  '/recess',
  '/settings',
  '/notifications',
  '/household-members',
  '/household-balance',
  '/momentum',
  '/weekly-report',
  '/places',
  '/smart-home',
  '/badge-gallery',
] as const;

export const POPPINS_TOOL_DEFINITIONS: PoppinsToolDefinition[] = [
  {
    name: 'list_overdue_tasks',
    description: 'List overdue or late open household tasks.',
    parameters: { type: 'object', properties: {}, additionalProperties: false },
    risk: 'safe_parallel',
  },
  {
    name: 'list_tasks',
