export const DEFAULT_MAJORDOMO_PROFILE_ID: MajordomoProfileId = 'poppins';

const PROFILE_BY_ID = Object.fromEntries(
  MAJORDOMO_PROFILES.map((p) => [p.id, p])
) as Record<MajordomoProfileId, MajordomoProfile>;

export function isMajordomoProfileId(value: unknown): value is MajordomoProfileId {
  return typeof value === 'string' && value in PROFILE_BY_ID;
}

export function getMajordomoProfile(id?: string | null): MajordomoProfile {
  if (id && isMajordomoProfileId(id)) return PROFILE_BY_ID[id];
  return PROFILE_BY_ID[DEFAULT_MAJORDOMO_PROFILE_ID];
}

export function resolveMajordomoProfileId(options: {
  householdProfileId?: string | null;
  memberProfileId?: string | null;
}): MajordomoProfileId {
  if (isMajordomoProfileId(options.memberProfileId)) return options.memberProfileId;
  if (isMajordomoProfileId(options.householdProfileId)) return options.householdProfileId;
  return DEFAULT_MAJORDOMO_PROFILE_ID;
}

/** Owner's rule: Poppins never says "UI" (or any other internal word for the screen). */
export const SPOKEN_WORDS_RULE = `

Words you say (and write): you are Poppins. Never say "UI" on its own, and never "IUI", "interface", "stage", "card", "beat", "HOLD", "widget" or "draft". The only names for yourself are "Poppins", "Poppins AI" or "the voice UI". Point at the screen with "here" or "on screen". If asked what this is: you're Poppins, the house's voice UI.`;

